const input = $json.body ?? $json;
const rawIp = input.ip ?? input.ipAddress ?? input.clientIp;
const ip = typeof rawIp === 'string' ? rawIp.trim() : '';
const errors = [];

if (!ip) {
  errors.push('Add an IP address in the ip field.');
} else {
  // Basic syntax guard only. IPGeolocation validates whether the address can be looked up.
  const looksLikeIp = ip.length <= 45 && /^[0-9a-fA-F:.]+$/.test(ip) && (ip.includes('.') || ip.includes(':'));
  if (!looksLikeIp) errors.push('The ip field must look like an IPv4 or IPv6 address.');
}

if (input.amount !== undefined && input.amount !== null && (typeof input.amount !== 'number' || !Number.isFinite(input.amount) || input.amount < 0)) {
  errors.push('amount must be a non-negative JSON number.');
}

return [{ json: {
  valid: errors.length === 0,
  validationErrors: errors,
  event: {
    ip,
    eventType: String(input.eventType ?? 'order.created'),
    orderId: input.orderId ?? null,
    customerId: input.customerId ?? null,
    amount: input.amount ?? null,
    currency: input.currency ?? null,
    source: input.source ?? 'webhook'
  },
  receivedAt: new Date().toISOString(),
  policyVersion: '1.0.0'
}}];

const request = $('Validate Request Data').item.json;
const event = request.event;
const response = $json ?? {};
const security = response.security && typeof response.security === 'object' ? response.security : null;

// If the node returns no security object, do not assume the IP is safe.
if (!security) {
  return { json: {
    success: false,
    status: 'LOOKUP_INCOMPLETE',
    event: { type: event.eventType, orderId: event.orderId, customerId: event.customerId, ip: event.ip },
    assessment: { recommendation: 'MANUAL_REVIEW', severity: 'unknown', workflowRiskScore: null, providerThreatScore: null, signals: [{ code: 'SECURITY_DATA_MISSING', explanation: 'The lookup did not contain a security object. No safe-IP conclusion was made.' }], nextActions: ['Check the IPGeolocation node output and API plan', 'Retry the lookup or review the event manually'] },
    audit: { receivedAt: request.receivedAt, assessedAt: new Date().toISOString(), policyVersion: request.policyVersion }
  } };
}

const bool = v => v === true || v === 1 || v === 'true';
const scoreRaw = security.threat_score;
const providerThreatScore = scoreRaw === undefined || scoreRaw === null || scoreRaw === '' || !Number.isFinite(Number(scoreRaw)) ? null : Math.max(0, Math.min(100, Number(scoreRaw)));
const flags = {
  isTor: bool(security.is_tor),
  isProxy: bool(security.is_proxy),
  isResidentialProxy: bool(security.is_residential_proxy),
  isVpn: bool(security.is_vpn),
  isRelay: bool(security.is_relay),
  isAnonymous: bool(security.is_anonymous),
  isKnownAttacker: bool(security.is_known_attacker),
  isBot: bool(security.is_bot),
  isKnownGoodBot: bool(security.is_known_good_bot),
  isSpam: bool(security.is_spam),
  isCloudProvider: bool(security.is_cloud_provider),
  isCorporateGateway: bool(security.is_corporate_gateway)
};

// This is an example workflow score, separate from IPGeolocation's provider threat_score. Tune for your own use case.
const signals = [];
let workflowRiskScore = 0;
const add = (condition, code, points, explanation) => { if (condition) { signals.push({ code, points, explanation }); workflowRiskScore += points; } };
add(flags.isKnownAttacker, 'KNOWN_ATTACKER', 45, 'IPGeolocation flags this IP as a known attacker.');
add(flags.isTor, 'TOR_EXIT_NODE', 25, 'IPGeolocation identifies this IP as a Tor exit node.');
add(flags.isResidentialProxy, 'RESIDENTIAL_PROXY', 20, 'IPGeolocation identifies this IP as a residential proxy.');
add(flags.isProxy && !flags.isResidentialProxy, 'PROXY_DETECTED', 10, 'IPGeolocation identifies proxy activity. Proxy use can have legitimate reasons.');
add(flags.isVpn, 'VPN_DETECTED', 10, 'IPGeolocation identifies VPN use. VPN use alone does not prove abuse.');
add(flags.isRelay, 'RELAY_DETECTED', 10, 'IPGeolocation identifies a relay service.');
add(flags.isAnonymous && !flags.isTor && !flags.isProxy && !flags.isVpn && !flags.isRelay, 'ANONYMOUS_ROUTE', 10, 'IPGeolocation identifies an anonymizing route.');
add(flags.isSpam, 'SPAM_SIGNAL', 20, 'IPGeolocation flags this IP for spam activity.');
add(flags.isBot && !flags.isKnownGoodBot, 'BOT_SIGNAL', 10, 'IPGeolocation identifies bot activity that is not marked as a known good bot.');
add(providerThreatScore !== null && providerThreatScore >= 81, 'HIGH_PROVIDER_THREAT_SCORE', 25, 'The IPGeolocation threat score is 81 or higher.');
add(providerThreatScore !== null && providerThreatScore >= 51 && providerThreatScore < 81, 'ELEVATED_PROVIDER_THREAT_SCORE', 15, 'The IPGeolocation threat score is between 51 and 80.');
workflowRiskScore = Math.min(100, workflowRiskScore);

// Corporate gateways and cloud hosting are included as context, not scored on their own. Known-good bots are not penalized as bad bots.
let recommendation = 'ALLOW_FOR_NORMAL_PROCESSING';
let severity = 'low';
if (workflowRiskScore >= 60) { recommendation = 'MANUAL_REVIEW'; severity = 'high'; }
else if (workflowRiskScore >= 25) { recommendation = 'ADDITIONAL_VERIFICATION'; severity = 'medium'; }

const nextActions = recommendation === 'MANUAL_REVIEW'
  ? ['Pause automated approval if your business process supports it', 'Review payment, account history, and shipping details', 'Do not reject the customer based on IP data alone']
  : recommendation === 'ADDITIONAL_VERIFICATION'
    ? ['Consider an appropriate step-up verification', 'Compare with payment and account signals', 'Allow a recovery path for legitimate customers']
    : ['Continue your normal process', 'Keep the assessment only as long as your policy requires'];

return { json: {
  success: true,
  status: 'ASSESSED',
  event: { type: event.eventType, orderId: event.orderId, customerId: event.customerId, amount: event.amount, currency: event.currency, ip: event.ip, source: event.source },
  assessment: { recommendation, severity, workflowRiskScore, providerThreatScore, signalCount: signals.length, signals, nextActions, requiresHumanReview: recommendation === 'MANUAL_REVIEW' },
  providerSignals: { ...flags, proxyProviderNames: security.proxy_provider_names ?? [], vpnProviderNames: security.vpn_provider_names ?? [], cloudProviderName: security.cloud_provider_name ?? '', botType: security.bot_type ?? '', botOperatorName: security.bot_operator_name ?? '', corporateGatewayType: security.corporate_gateway_type ?? '', corporateGatewayProviderName: security.corporate_gateway_provider_name ?? '' },
  audit: { receivedAt: request.receivedAt, assessedAt: new Date().toISOString(), policyVersion: request.policyVersion, engine: 'IPGeolocation n8n security risk review template' },
  notes: ['workflowRiskScore is an example score created by this workflow, not an IPGeolocation field.', 'Cloud-provider and corporate-gateway flags are shown for context and do not add risk points by themselves.']
} };
